"""English Standard Paper 2 (Modules A, B, C) quick questions, added to the shared Paper 1 set for English Standard.
All extracts are original, written for Trialbank. Run after english.py."""
import json, os
from lib import Bank, OUT
b = Bank('quick-engstd-p2', 'engstd', typed=True, seed=82)
M, W = b.M, b.W
q = lambda s: f'<i>“{s}”</i>'
def X(mk, what='with well-chosen references'):
    bands = {2: [('Explains clearly ' + what, 2), ('Identifies a relevant point', 1)],
             3: [('Explains clearly and in detail ' + what, 3), ('Explains with some reference', 2), ('Identifies a relevant point', 1)],
             4: [('Insightful, well-structured explanation ' + what, 4), ('Clear explanation with relevant references', 3), ('Describes with some reference', 2), ('Limited or general response', 1)],
             5: [('Insightful thesis; sophisticated analysis ' + what + '; well structured', 5), ('Clear thesis; effective analysis with relevant references', 4), ('Sound explanation with some references', 3), ('Describes with limited reference to techniques', 2), ('General or limited response', 1)]}
    return bands[mk]

A = 'Module A: Language, Identity and Culture'
M(A, 'Module A explores how', 'language shapes and expresses personal and cultural identity', ['writers choose a genre', 'texts are published', 'plots are structured into acts'], 'It asks how language reflects and shapes who we are and the groups we belong to.')
M(A, 'A writer who mixes English with words from their home language is most likely showing', 'a hybrid or bicultural identity', ['a lack of vocabulary', 'formal register', 'an unreliable narrator'], 'Code-switching shows belonging to more than one culture.')
M(A, 'Code-switching means', 'moving between languages or varieties of a language depending on context', ['translating a text word for word', 'changing the narrator mid-story', 'using only formal language'], 'Speakers shift register or language to fit the audience.')
M(A, 'Colloquial language and slang in a text usually suggest', 'informality and belonging to a particular group or place', ['an academic audience', 'a historical setting only', 'a lack of identity'], 'Vernacular marks group identity.')
M(A, 'When a character is forced to give up their language, a text is most likely exploring', 'loss of cultural identity', ['the joy of travel', 'romantic love', 'scientific progress'], 'Language loss often stands for cultural dispossession.')
M(A, 'A first-person, conversational voice in a memoir helps the composer to', 'present their identity as personal and authentic', ['seem objective and distant', 'describe events they did not see', 'avoid emotion'], 'Voice is a key way identity is expressed.')
M(A, 'Collective pronouns such as "we" and "our" in a speech create', 'a sense of shared identity and solidarity', ['distance from the audience', 'a formal legal tone', 'confusion about the speaker'], 'Inclusive language builds belonging.')
M(A, 'The phrase "language, identity and culture" suggests that', 'the three are connected and shape each other', ['language is unrelated to culture', 'identity never changes', 'culture is only about food and festivals'], 'Module A treats them as interwoven.')
M(A, 'Which technique best shows how others label or stereotype a character?', 'Dialogue in which others name or describe them', ['Pathetic fallacy', 'A flashback to childhood', 'A list of settings'], 'How others speak about someone can impose an identity on them.')
M(A, 'Reclaiming a word that was once used as an insult is an example of', 'using language to assert identity and power', ['a spelling error', 'an oxymoron', 'formal register'], 'Groups can take back language used against them.')
M(A, 'Silence or an unfinished sentence in a text about migration can suggest', 'difficulty expressing identity in a new language', ['confidence and fluency', 'a happy ending', 'a change of setting'], 'Gaps in language mirror gaps in belonging.')
M(A, 'In a poem, writing some lines in an Aboriginal language without translation can', 'assert the value and survival of that culture', ['make the poem formal', 'show the poet forgot English', 'create humour only'], 'Leaving it untranslated centres that culture.')
W(A, 2, f'Read the line: {q("At school I was Kate. At home I was Kalinda, and the name fit me like my grandmother’s ring.")} Explain how the line represents identity.', ['The juxtaposition of the two names shows a split identity between the school (mainstream) culture and home culture.', 'The simile "fit me like my grandmother\'s ring" links her true name to family heritage, suggesting her home identity feels authentic and precious.'], X(2, 'with reference to the line'))
W(A, 3, f'Read the extract: {q("They corrected my vowels until my mouth was theirs. Now when I call my mother, she says I sound like the radio.")} Explain how the extract represents the relationship between language and identity.', ['The metaphor "until my mouth was theirs" shows language being taken over, suggesting the speaker\'s identity is reshaped by those in power.', 'The pronoun contrast "my" and "theirs" shows a struggle over ownership of identity.', 'The mother\'s comment, "I sound like the radio", shows the cost: the speaker now sounds foreign to their own family, so changing language has distanced them from their culture.'], X(3, 'with reference to the extract'))
W(A, 2, 'Outline how a composer can use language to show that identity changes over time.', ['Changes in a character\'s voice, vocabulary or language choice across a text (e.g. from their home language to English, or from childish to formal speech) show identity developing.', 'Structure such as flashbacks or contrasting sections can set an earlier self beside a later self.'], X(2, 'with examples of techniques'))
W(A, 5, f'Read the extract: {q("My father spoke two languages: one for the shop and one for the kitchen. In the shop he said Sir and Thank you and Have a good day. In the kitchen he sang, he swore, he told stories about a river I had never seen. I learned early which father I preferred, and later, which one had kept us fed.")} Analyse how the extract represents the ways language shapes identity and belonging.', ['Thesis: language divides the father\'s identity into a public, assimilated self and a private, cultural self, and the child comes to see the value of both.', 'Contrast and repetition ("one for the shop and one for the kitchen") structure the split identity.', 'Listing of polite formulas ("Sir and Thank you and Have a good day") shows a restricted, performed identity, while the energetic verbs "sang, he swore, he told" show freedom and authenticity.', '"a river I had never seen" shows inherited cultural memory the child belongs to only through language.', 'The final sentence\'s parallel structure ("which father I preferred ... which one had kept us fed") shows mature recognition of the sacrifice of adopting a new language.'], X(5, 'of how several techniques represent identity and belonging'))

B_ = 'Module B: Close Study of Literature'
M(B_, 'Module B asks students to', 'study one prescribed text closely and in depth', ['compare two unrelated texts', 'write their own short story', 'study only unseen texts'], 'Close study of a single literary text.')
M(B_, 'The "distinctive qualities" of a text refers to', 'the features that make it unique and valued, such as its ideas, form and style', ['its page count', 'its price', 'the author\'s birthplace only'], 'What makes the text worth studying.')
M(B_, 'Analysing a character\'s development across a whole text involves', 'tracing how they change and what causes the change', ['describing their first scene only', 'retelling the plot', 'listing every character'], 'Development is shown over the structure of the text.')
M(B_, 'An effective quotation in an essay is', 'short, relevant and followed by analysis of its effect', ['very long and left without comment', 'a summary of the plot', 'taken from a study guide'], 'Embed, then explain the technique and meaning.')
M(B_, 'A motif is', 'a recurring image, idea or symbol that develops meaning', ['the main character', 'a single line of dialogue', 'the title only'], 'Repetition across the text builds significance.')
M(B_, 'In a novel, the narrative point of view affects', 'what the reader knows and how they judge characters', ['only the font', 'the length of chapters only', 'nothing important'], 'Perspective shapes the reader\'s response.')
M(B_, 'Context matters in Module B because', 'the time and place a text was composed shape its values and ideas', ['every text has the same context', 'readers must ignore history', 'it replaces close reading'], 'Context helps explain why the text represents ideas as it does.')
M(B_, 'In a drama, stage directions can reveal', 'characters\' emotions and relationships without dialogue', ['the playwright\'s address', 'the price of tickets', 'only lighting cues'], 'Movement, pauses and gestures carry meaning.')
M(B_, 'A topic sentence in a Module B paragraph should', 'state a clear point that supports the thesis', ['retell the plot', 'introduce a new text', 'list techniques without a point'], 'Each paragraph argues one idea.')
M(B_, 'Dramatic irony occurs when', 'the audience knows something a character does not', ['a character speaks to themselves', 'the weather matches the mood', 'two opposite words are joined'], 'It creates tension or sympathy.')
M(B_, 'The resolution of a text is significant because it', 'reveals the composer\'s final position on the main ideas', ['is always happy', 'introduces new characters', 'has no meaning'], 'Endings shape the overall message.')
M(B_, 'A useful way to plan a Module B essay is to', 'organise paragraphs around ideas, each supported by several pieces of evidence', ['write one paragraph per chapter', 'list techniques alphabetically', 'summarise the text first'], 'Idea-based structure keeps the argument clear.')
W(B_, 2, 'Outline the difference between summarising a text and analysing it.', ['Summarising retells what happens in the text.', 'Analysing explains how the composer uses techniques and form to create meaning and why, supported by evidence.'], X(2, 'with the distinction made clear'))
W(B_, 3, 'Explain how a composer can use a symbol to develop an idea across a text. Use an example from your prescribed text or an invented example.', ['A symbol is an object or image that stands for an idea, e.g. a locked gate representing exclusion.', 'When it reappears at key moments (the gate closed at the start, the character climbing it in the middle, the gate left open at the end), its meaning develops.', 'This lets the composer show a change, such as a character moving from exclusion to belonging, without stating it directly.'], X(3, 'with a developed example'))
W(B_, 4, 'Write a Module B body paragraph plan on how your prescribed text represents a central idea. Include a topic sentence, three pieces of evidence and the link to the question.', ['Topic sentence that makes a clear argument about the idea (not a plot point).', 'Three pieces of evidence from different parts of the text, each with a technique and an explanation of its effect.', 'A linking sentence that connects the paragraph back to the question and thesis.'], X(4, 'with relevant, well-chosen evidence'))
W(B_, 5, 'Explain how the distinctive qualities of your prescribed text shape its representation of one central idea.', ['A clear thesis naming the idea and the distinctive qualities (e.g. its form, narrative voice, structure, imagery).', 'Analysis of how each quality shapes meaning, supported by quotations or specific references from across the text.', 'Consideration of context or audience where it explains why the idea is represented this way.', 'A sustained, well-structured response that answers the question in every paragraph.'], X(5, 'of the text\'s distinctive qualities'))

C = 'Module C: The Craft of Writing'
M(C, 'Module C focuses on', 'students\' own writing and the craft choices writers make', ['a single prescribed novel', 'unseen texts only', 'film techniques only'], 'Writers learn craft from model texts and apply it.')
M(C, 'An imaginative piece should usually', 'show rather than tell, using concrete detail', ['explain every emotion directly', 'avoid any description', 'be written as a list of facts'], 'Readers infer feelings from precise detail.')
M(C, 'A discursive piece is', 'an exploration of an idea from several perspectives without needing to reach one conclusion', ['a persuasive speech with one clear contention', 'a short story with a twist', 'a formal report'], 'It meanders and reflects, often in a personal voice.')
M(C, 'A persuasive piece needs', 'a clear contention supported by evidence and appeals', ['no clear position', 'a fictional narrator only', 'mainly dialogue'], 'Logos, ethos and pathos support the contention.')
M(C, 'Starting a story in the middle of the action is called', 'in medias res', ['a flashback', 'a frame narrative', 'denouement'], 'It hooks the reader immediately.')
M(C, 'A reflection statement in Module C should', 'explain the writer\'s choices and their intended effects', ['retell the story', 'list spelling corrections', 'praise the writing without detail'], 'It justifies craft decisions with examples.')
M(C, 'A cyclical structure ends a piece by', 'returning to an image or line from the opening', ['introducing a new character', 'skipping to the future', 'ending mid-sentence'], 'It creates unity and shows change.')
M(C, 'Varying sentence length helps writers to', 'control pace and emphasis', ['meet the word limit only', 'avoid using verbs', 'make paragraphs equal'], 'Short sentences can create tension or impact.')
M(C, 'Which opening best "shows" fear?', q("Her keys rattled against the lock twice before she got the door open."), [q("She was very scared."), q("Fear is a feeling everyone has."), q("It was a scary night and she felt fear.")], 'Physical detail lets the reader infer fear.')
M(C, 'Using a single strong verb instead of a verb plus adverb, e.g. "she sprinted" not "she ran quickly", makes writing', 'more precise and vivid', ['longer', 'more formal only', 'less clear'], 'Precise diction is a key craft skill.')
M(C, 'A limited third-person narrator', 'follows one character\'s thoughts while using "he" or "she"', ['knows every character\'s thoughts', 'uses "I"', 'speaks directly to the reader as "you"'], 'It combines closeness with some distance.')
M(C, 'Choosing a title for an imaginative piece is part of the craft because it', 'can foreshadow, frame or add a layer of meaning', ['has no effect on the reader', 'must summarise the plot', 'is marked separately'], 'Titles shape expectations.')
W(C, 2, f'Rewrite this sentence to show rather than tell: {q("The old man was lonely.")} Then explain your choice.', ['Example: "The old man set two cups on the table every morning, then put one back."', 'The action shows loneliness through an implied absence, so the reader feels it rather than being told.'], X(2, 'with an effective rewrite and explanation'))
W(C, 3, 'Explain how a writer can use setting to create mood in an imaginative piece. Give an example.', ['Setting details chosen for sensory impact (sound, light, texture) suggest an emotional atmosphere.', 'Example: "Fluorescent lights hummed over rows of empty chairs" creates an unsettling, lonely mood.', 'Pathetic fallacy or a change in setting can mirror a character\'s inner state and signal a shift in the story.'], X(3, 'with an example'))
W(C, 3, 'Write the opening (about 80 to 100 words) of a short story that begins in medias res, then explain one craft choice you made.', ['An opening that drops the reader into action or tension without background explanation.', 'Precise sensory detail and varied sentence length to control pace.', 'A short explanation of one choice (e.g. a fragment to create urgency) and its intended effect.'], X(3, 'with an effective opening and explanation of a craft choice'))
W(C, 4, 'Write a short reflection (about 150 words) explaining how you used one technique from a model text in your own imaginative writing.', ['Names the model text and the technique (e.g. a recurring motif, cyclical structure, second-person voice).', 'Explains how it is used in the model text and the effect it creates.', 'Explains how and where it was adapted in your own writing, with a short quotation from your piece.', 'Reflects on the effect on your reader and your purpose.'], X(4, 'linking the model text to your own writing'))
W(C, 5, 'Compose a discursive piece (about 300 words) that explores the idea of home. Use at least two perspectives.', ['A personal, reflective voice that explores rather than argues.', 'At least two different perspectives on home (e.g. a place, people, a feeling, a memory).', 'Anecdote, imagery and a meandering but controlled structure, possibly cyclical.', 'Language crafted for effect (varied sentences, precise diction) and a thoughtful ending that need not resolve the idea.'], X(5, 'in its control of discursive form and language'))
b.save()

# English Standard = shared Paper 1 set + Paper 2 set
for kind in ('', '-worked'):
    std = json.load(open(os.path.join(OUT, f'quick-engstd{kind}.raw.json')))
    p2 = json.load(open(os.path.join(OUT, f'quick-engstd-p2{kind}.raw.json')))
    json.dump(std + p2, open(os.path.join(OUT, f'quick-engstd{kind}.raw.json'), 'w'), ensure_ascii=False)
    print(f'quick-engstd{kind}', len(std) + len(p2))
